package com.fmrent.cars.service;
import com.fmrent.cars.dto.CarResponse; import com.fmrent.cars.model.Car; import com.fmrent.cars.repository.CarRepository; import java.math.BigDecimal; import java.util.List; import org.springframework.http.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import org.springframework.web.multipart.MultipartFile; import org.springframework.web.server.ResponseStatusException;
@Service public class CarService {private final CarRepository cars;private final ImageKitService images;public CarService(CarRepository cars,ImageKitService images){this.cars=cars;this.images=images;}
 @Transactional(readOnly=true) public List<CarResponse> list(){return cars.findAllByOrderByCreatedAtDesc().stream().map(CarResponse::from).toList();}
 @Transactional(readOnly=true) public CarResponse get(Long id){return cars.findById(id).map(CarResponse::from).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Voiture introuvable."));}
 @Transactional public CarResponse create(String name,String category,BigDecimal price,int seats,String transmission,String fuel,String badge,List<MultipartFile> files){if(files==null||files.isEmpty()||files.size()>8)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Ajoutez entre 1 et 8 images.");if(files.stream().anyMatch(f->f.isEmpty()||f.getContentType()==null||!f.getContentType().startsWith("image/")))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Toutes les images doivent être valides.");var uploaded=files.stream().map(images::upload).toList();var gallery=new java.util.ArrayList<com.fmrent.cars.model.CarImage>();for(int i=0;i<uploaded.size();i++){var item=uploaded.get(i);gallery.add(new com.fmrent.cars.model.CarImage(item.url(),item.fileId(),i));}var cover=uploaded.get(0);return CarResponse.from(cars.save(new Car(name.trim(),category,price,seats,transmission,fuel,badge==null||badge.isBlank()?null:badge.trim(),cover.url(),cover.fileId(),gallery)));}
 @Transactional public void delete(Long id){var car=cars.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Voiture introuvable."));var ids=car.getImages().stream().map(com.fmrent.cars.model.CarImage::getFileId).distinct().toList();if(ids.isEmpty())images.delete(car.getImageFileId());else ids.forEach(images::delete);cars.delete(car);}}
